import React from 'react'
import ReactDOM from 'react-dom/client'
import { RouterProvider, createRouter, createRootRoute, createRoute } from '@tanstack/react-router'
import { SearchPage } from './SearchPage'
import './index.css'

const rootRoute = createRootRoute()

const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  component: () => (
    <main>
      <h1>Home</h1>
      <p>Navigate to <a href="/search">/search</a> to try the search page.</p>
    </main>
  ),
})

const searchRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/search',
  validateSearch: (search: Record<string, unknown>) => ({
    q: (search.q as string) ?? '',
    category: (search.category as string) ?? '',
    minPrice: Number(search.minPrice) || 0,
    maxPrice: Number(search.maxPrice) || 0,
  }),
  component: SearchPage,
})

const routeTree = rootRoute.addChildren([indexRoute, searchRoute])

const router = createRouter({ routeTree })

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
}

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <RouterProvider router={router} />
  </React.StrictMode>,
)

import { useSearch, useNavigate } from '@tanstack/react-router'
import { useCallback } from 'react'

export function SearchPage() {
  const search = useSearch({ strict: false }) as {
    q: string
    category: string
    minPrice: number
    maxPrice: number
  }
  const navigate = useNavigate()

  const updateFilter = useCallback(
    (key: string, value: string) => {
      navigate({
        to: '/search',
        search: (prev: Record<string, string | number>) => {
          const next = { ...prev }
          if (key === 'minPrice' || key === 'maxPrice') {
            const parsed = Number(value)
            next[key] = isNaN(parsed) ? 0 : parsed
          } else {
            next[key] = value
          }
          return next
        },
        replace: true,
      })
    },
    [navigate],
  )

  return (
    <main>
      <h1>Search</h1>

      <div className="filter-group">
        <label htmlFor="q">Search query</label>
        <input
          name="q"
          id="q"
          type="text"
          placeholder="Search products..."
          value={search.q ?? ''}
          onChange={(e) => updateFilter('q', e.target.value)}
        />
      </div>

      <div className="filter-group">
        <label htmlFor="category">Category</label>
        <input
          name="category"
          id="category"
          type="text"
          placeholder="e.g. electronics"
          value={search.category ?? ''}
          onChange={(e) => updateFilter('category', e.target.value)}
        />
      </div>

      <div className="price-row">
        <div className="filter-group">
          <label htmlFor="minPrice">Min Price</label>
          <input
            name="minPrice"
            id="minPrice"
            type="number"
            min={0}
            placeholder="0"
            value={search.minPrice ?? 0}
            onChange={(e) => updateFilter('minPrice', e.target.value)}
          />
        </div>

        <div className="filter-group">
          <label htmlFor="maxPrice">Max Price</label>
          <input
            name="maxPrice"
            id="maxPrice"
            type="number"
            min={0}
            placeholder="1000"
            value={search.maxPrice ?? 0}
            onChange={(e) => updateFilter('maxPrice', e.target.value)}
          />
        </div>
      </div>

      <div className="current-url">
        <strong>Current search params:</strong>
        <pre>{JSON.stringify(search, null, 2)}</pre>
      </div>
    </main>
  )
}

